#include <bits/stdc++.h>
#include <chrono>
using namespace std; using namespace std::chrono;
static constexpr double BASE_GRID=1.0, RT_COMM=0.07, DAILY_TARGET=10.0, LEVERAGE=2000.0;
struct Basket{bool active=false,danger=false;double zero=0;int buys=0,sells=0;double buySum=0,sellSum=0;int mp=0,mn=0;double nextPos=0,nextNeg=0;int size()const{return buys+sells;}};
struct Day{int date=0;double realized=0;bool target=false,marginFail=false,accountFail=false;int baskets=0,wins=0,fridayCloses=0,orders=0,maxOpen=0;double minEquity=1e100,maxMargin=0;};
bool parse(const string&l,int&date,int&sec,double&bid,double&ask){if(l.empty()||l[0]!='\"'||l.rfind("\"Exness\"",0)==0)return false;size_t c1=l.find(','),c2=l.find(',',c1+1),c3=l.find(',',c2+1),c4=l.find(',',c3+1);if(c4==string::npos)return false;string t=l.substr(c2+1,c3-c2-1);if(!t.empty()&&t.front()=='\"')t.erase(t.begin());if(!t.empty()&&t.back()=='\"')t.pop_back();if(t.size()<19)return false;date=stoi(t.substr(0,4))*10000+stoi(t.substr(5,2))*100+stoi(t.substr(8,2));sec=stoi(t.substr(11,2))*3600+stoi(t.substr(14,2))*60+stoi(t.substr(17,2));bid=strtod(l.c_str()+c3+1,nullptr);ask=strtod(l.c_str()+c4+1,nullptr);return bid>0&&ask>=bid;}
int wd(int date){int y=date/10000,m=(date/100)%100,d=date%100;weekday w{sys_days{year{y}/month{(unsigned)m}/day{(unsigned)d}}};return w.c_encoding();}
inline double liq(const Basket&b,double bid,double ask){if(!b.active)return 0;return b.buys*bid-b.buySum+b.sellSum-b.sells*ask-RT_COMM*b.size();}
inline double margin(const Basket&b,double mid){return b.size()*mid/LEVERAGE;}
struct Sim{double balance=1000;bool alive=true;Basket b;Day d;bool stopped=false;long long hk=LLONG_MIN;double hh=-1e100,hl=1e100,lastH=0,lastL=0;bool lastHV=false;double rH=0,rL=0;bool rV=false,armed=false,needIn=false;double lb=0,la=0;int K=10;double W=3;bool noFriday=true;};
void newDay(Sim&s,int date){s.d=Day();s.d.date=date;s.d.minEquity=s.balance+liq(s.b,s.lb,s.la);s.stopped=false;}
void risk(Sim&s,double bid,double ask){if(!s.alive)return;double eq=s.balance+liq(s.b,bid,ask);s.d.minEquity=min(s.d.minEquity,eq);s.d.maxOpen=max(s.d.maxOpen,s.b.size());s.d.maxMargin=max(s.d.maxMargin,margin(s.b,(bid+ask)/2));if(eq<=0){s.alive=false;s.d.accountFail=true;s.balance=0;}}
bool canOpen(const Sim&s,double bid,double ask){double eq=s.balance+liq(s.b,bid,ask);double nm=(s.b.size()+1)*((bid+ask)/2)/LEVERAGE;return eq>=nm;}
void setR(Sim&s,bool need){if(s.lastHV){s.rH=s.lastH;s.rL=s.lastL;s.rV=true;s.needIn=need;s.armed=!need;}}
void closeB(Sim&s,double bid,double ask,bool win,bool fri){double q=liq(s.b,bid,ask);s.balance+=q;s.d.realized+=q;if(win)s.d.wins++;if(fri)s.d.fridayCloses++;s.b=Basket();setR(s,true);if(s.balance<=0){s.balance=0;s.alive=false;s.d.accountFail=true;}if(s.d.realized>=DAILY_TARGET-1e-12){s.d.target=true;s.stopped=true;}}
void startB(Sim&s,int side,double bid,double ask){if(!canOpen(s,bid,ask)){s.d.marginFail=true;s.alive=false;return;}s.b=Basket();s.b.active=true;s.b.zero=bid;double f=side==1?ask:bid;if(side==1){s.b.buys=1;s.b.buySum=f;}else{s.b.sells=1;s.b.sellSum=f;}s.d.baskets++;s.d.orders++;s.armed=false;risk(s,bid,ask);}
void add(Sim&s,int side,double bid,double ask){if(!canOpen(s,bid,ask)){s.d.marginFail=true;s.alive=false;return;}double f=side==1?ask:bid;if(side==1){s.b.buys++;s.b.buySum+=f;}else{s.b.sells++;s.b.sellSum+=f;}s.d.orders++;risk(s,bid,ask);}
void maybeDanger(Sim&s){if(s.K<=0||s.b.danger)return;int bal=min(s.b.mp,-s.b.mn);if(bal>=s.K){s.b.danger=true;s.b.nextPos=s.b.mp+s.W;s.b.nextNeg=s.b.mn-s.W;}}
void printH(){cout<<"date,realized_pnl,target_hit,margin_fail,account_fail,baskets,cycle_wins,friday_closes,total_orders,max_open,min_equity,max_margin_1_2000,balance_end\n";}
void printD(const Sim&s){auto&d=s.d;cout<<d.date<<","<<fixed<<setprecision(6)<<d.realized<<","<<d.target<<","<<d.marginFail<<","<<d.accountFail<<","<<d.baskets<<","<<d.wins<<","<<d.fridayCloses<<","<<d.orders<<","<<d.maxOpen<<","<<d.minEquity<<","<<d.maxMargin<<","<<s.balance<<"\n";}
int main(int argc,char**argv){ios::sync_with_stdio(false);cin.tie(nullptr);Sim s;if(argc>1)s.K=stoi(argv[1]);if(argc>2)s.W=stod(argv[2]);if(argc>3)s.noFriday=stoi(argv[3])!=0;printH();string line;bool have=false;while(getline(cin,line)){int date,sec;double bid,ask;if(!parse(line,date,sec,bid,ask))continue;if(!have){s.lb=bid;s.la=ask;newDay(s,date);have=true;}if(date!=s.d.date){if(s.alive&&wd(s.d.date)==5&&s.b.active)closeB(s,s.lb,s.la,false,true);printD(s);if(!s.alive)return 0;newDay(s,date);}s.lb=bid;s.la=ask;long long hk=(long long)date*24+sec/3600;if(s.hk==LLONG_MIN){s.hk=hk;s.hh=s.hl=bid;risk(s,bid,ask);continue;}if(hk!=s.hk){s.lastH=s.hh;s.lastL=s.hl;s.lastHV=s.hh>s.hl;if(!s.b.active&&!s.stopped&&wd(date)>=1&&wd(date)<=5)setR(s,false);s.hk=hk;s.hh=s.hl=bid;}else{s.hh=max(s.hh,bid);s.hl=min(s.hl,bid);}risk(s,bid,ask);if(!s.alive){printD(s);return 0;}int w=wd(date);if(w==0||w==6||s.stopped)continue;if(!s.b.active){if(s.noFriday&&w==5)continue;if(!s.rV)continue;if(s.needIn){if(bid<=s.rH&&bid>=s.rL){s.needIn=false;s.armed=true;}else continue;}if(!s.armed)continue;if(bid>s.rH)startB(s,1,bid,ask);else if(bid<s.rL)startB(s,-1,bid,ask);if(!s.alive){printD(s);return 0;}continue;}double q=liq(s.b,bid,ask);if(s.d.realized+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,false,false);continue;}maybeDanger(s);if(!s.b.danger){bool cp=bid>=s.b.zero+(s.b.mp+1)*BASE_GRID,cn=bid<=s.b.zero+(s.b.mn-1)*BASE_GRID;if(cp){while(s.alive&&s.b.active&&!s.b.danger&&bid>=s.b.zero+(s.b.mp+1)*BASE_GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,true,false);break;}s.b.mp++;add(s,1,bid,ask);if(!s.alive)break;maybeDanger(s);q=liq(s.b,bid,ask);if(s.d.realized+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,false,false);break;}}}else if(cn){while(s.alive&&s.b.active&&!s.b.danger&&bid<=s.b.zero+(s.b.mn-1)*BASE_GRID){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,true,false);break;}s.b.mn--;add(s,-1,bid,ask);if(!s.alive)break;maybeDanger(s);q=liq(s.b,bid,ask);if(s.d.realized+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,false,false);break;}}}}
        if(s.b.active&&s.b.danger){bool cp=bid>=s.b.zero+s.b.nextPos,cn=bid<=s.b.zero+s.b.nextNeg;if(cp){while(s.alive&&s.b.active&&s.b.danger&&bid>=s.b.zero+s.b.nextPos){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,true,false);break;}add(s,1,bid,ask);if(!s.alive)break;s.b.mp=(int)floor(s.b.nextPos+1e-9);s.b.nextPos+=s.W;q=liq(s.b,bid,ask);if(s.d.realized+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,false,false);break;}}}else if(cn){while(s.alive&&s.b.active&&s.b.danger&&bid<=s.b.zero+s.b.nextNeg){q=liq(s.b,bid,ask);if(q>0){closeB(s,bid,ask,true,false);break;}add(s,-1,bid,ask);if(!s.alive)break;s.b.mn=(int)ceil(s.b.nextNeg-1e-9);s.b.nextNeg-=s.W;q=liq(s.b,bid,ask);if(s.d.realized+q>=DAILY_TARGET-1e-12){closeB(s,bid,ask,false,false);break;}}}}
        if(!s.alive){printD(s);return 0;}}
    if(have){if(s.alive&&wd(s.d.date)==5&&s.b.active)closeB(s,s.lb,s.la,false,true);printD(s);}return 0;}
